.articulo-propio{
      --azul:        #132E6A;
      --azul-mid:    #1a3d8a;
      --azul-claro:  #94bdd5;
      --gris:        #808080;
      --gris-claro:  #D1D1CF;
      --blanco:      #ffffff;
      --fondo:       #f4f6fa;
      --texto:       #1a1a2e;
      --texto-suave: #4a5568;
    }
.articulo-propio *, .articulo-propio *::before, .articulo-propio *::after{ box-sizing: border-box; margin: 0; padding: 0; }
.articulo-propio{ scroll-behavior: smooth; }
.articulo-propio{
      font-family: 'Montserrat', sans-serif;
      background: var(--fondo);
      color: var(--texto);
      line-height: 1.7;
      overflow-x: hidden;
      -webkit-text-size-adjust: 100%;
    }
.articulo-propio img{ display: block; max-width: 100%; }
.articulo-propio nav{
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 200;
      background: var(--azul);
      height: 60px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 clamp(16px, 4vw, 48px);
      box-shadow: 0 2px 20px rgba(19,46,106,0.4);
    }
.articulo-propio .nav-logo{
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      flex-shrink: 0;
    }
.articulo-propio .nav-logo-icon{
      width: 32px; height: 32px;
      background: var(--blanco);
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1rem;
      flex-shrink: 0;
    }
.articulo-propio .nav-logo-text{
      font-size: clamp(0.95rem, 3vw, 1.2rem);
      font-weight: 800;
      color: var(--blanco);
      letter-spacing: 0.08em;
    }
.articulo-propio .nav-logo-sub{
      font-size: 0.5rem;
      letter-spacing: 0.2em;
      color: var(--azul-claro);
      text-transform: uppercase;
      display: block;
      line-height: 1;
      margin-top: 2px;
    }
.articulo-propio .nav-cta{
      background: var(--azul-claro);
      color: var(--azul);
      font-size: clamp(0.65rem, 2vw, 0.78rem);
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      padding: 9px clamp(12px, 3vw, 20px);
      border-radius: 3px;
      text-decoration: none;
      white-space: nowrap;
      transition: background 0.2s;
      flex-shrink: 0;
    }
.articulo-propio .nav-cta:hover{ background: var(--blanco); }
.articulo-propio .hero{
      background: var(--azul);
      padding-top: 60px;
      position: relative;
      overflow: hidden;
    }
.articulo-propio .hero-bg-grid{
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(148,189,213,0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148,189,213,0.05) 1px, transparent 1px);
      background-size: 48px 48px;
      pointer-events: none;
    }
.articulo-propio .hero-bg-glow{
      position: absolute;
      bottom: -80px; right: -80px;
      width: min(500px, 80vw);
      height: min(500px, 80vw);
      background: radial-gradient(circle, rgba(148,189,213,0.08) 0%, transparent 70%);
      pointer-events: none;
    }
.articulo-propio .hero-inner{
      position: relative;
      z-index: 2;
      max-width: 1100px;
      margin: 0 auto;
      padding: clamp(48px, 8vw, 100px) clamp(20px, 5vw, 48px) clamp(52px, 8vw, 88px);
      display: grid;
      grid-template-columns: 1fr auto;
      gap: clamp(24px, 4vw, 60px);
      align-items: center;
    }
.articulo-propio .hero-label{
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(148,189,213,0.15);
      border: 1px solid rgba(148,189,213,0.3);
      color: var(--azul-claro);
      font-size: clamp(0.6rem, 1.5vw, 0.72rem);
      font-weight: 600;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      padding: 7px 14px;
      border-radius: 2px;
      margin-bottom: clamp(16px, 3vw, 28px);
    }
.articulo-propio .hero-label-dot{
      width: 6px; height: 6px;
      background: var(--azul-claro);
      border-radius: 50%;
      flex-shrink: 0;
      animation: pulse 1.5s ease-in-out infinite;
    }
.articulo-propio .hero h1{
      font-size: clamp(1.8rem, 5vw, 3.8rem);
      font-weight: 700;
      color: var(--blanco);
      line-height: 1.1;
      letter-spacing: -0.01em;
      margin-bottom: clamp(14px, 2.5vw, 24px);
    }
.articulo-propio .hero h1 em{
      font-style: normal;
      color: var(--azul-claro);
    }
.articulo-propio .hero-desc{
      font-size: clamp(0.85rem, 2vw, 1rem);
      color: rgba(255,255,255,0.65);
      line-height: 1.8;
      margin-bottom: clamp(24px, 4vw, 40px);
      font-weight: 300;
      max-width: 540px;
    }
.articulo-propio .hero-btns{
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }
.articulo-propio .btn-primary{
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--blanco);
      color: var(--azul);
      font-size: clamp(0.75rem, 2vw, 0.88rem);
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      padding: clamp(12px, 2vw, 16px) clamp(18px, 3vw, 30px);
      border-radius: 3px;
      text-decoration: none;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 20px rgba(0,0,0,0.2);
      white-space: nowrap;
    }
.articulo-propio .btn-primary:hover{ transform: translateY(-2px); box-shadow: 0 8px 28px rgba(0,0,0,0.25); }
.articulo-propio .btn-outline{
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: transparent;
      color: rgba(255,255,255,0.65);
      font-size: clamp(0.75rem, 2vw, 0.85rem);
      font-weight: 500;
      padding: clamp(12px, 2vw, 16px) clamp(14px, 2.5vw, 24px);
      border-radius: 3px;
      text-decoration: none;
      border: 1px solid rgba(255,255,255,0.2);
      transition: border-color 0.2s, color 0.2s;
      white-space: nowrap;
    }
.articulo-propio .btn-outline:hover{ border-color: var(--azul-claro); color: var(--azul-claro); }
.articulo-propio .hero-card{
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(148,189,213,0.2);
      border-radius: 8px;
      padding: clamp(20px, 3vw, 32px) clamp(18px, 2.5vw, 28px);
      min-width: 220px;
      max-width: 280px;
      flex-shrink: 0;
    }
.articulo-propio .hero-card-title{
      font-size: 0.62rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      color: var(--azul-claro);
      font-weight: 600;
      margin-bottom: 20px;
      padding-bottom: 12px;
      border-bottom: 1px solid rgba(148,189,213,0.15);
    }
.articulo-propio .hero-stat{
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 0;
      border-bottom: 1px solid rgba(148,189,213,0.08);
    }
.articulo-propio .hero-stat:last-child{ border-bottom: none; }
.articulo-propio .hero-stat-num{
      font-size: 1.6rem;
      font-weight: 700;
      color: var(--blanco);
      line-height: 1;
      white-space: nowrap;
      flex-shrink: 0;
    }
.articulo-propio .hero-stat-num span{
      font-size: 0.75rem;
      color: var(--azul-claro);
    }
.articulo-propio .hero-stat-label{
      font-size: 0.7rem;
      color: rgba(255,255,255,0.5);
      font-weight: 300;
      line-height: 1.4;
    }
.articulo-propio .section-intro{
      max-width: 800px;
      margin: 0 auto;
      padding: clamp(52px, 8vw, 80px) clamp(20px, 5vw, 40px) clamp(40px, 6vw, 60px);
      text-align: center;
    }
.articulo-propio .section-tag{
      display: inline-block;
      font-size: 0.68rem;
      font-weight: 600;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      color: var(--azul);
      border-left: 3px solid var(--azul-claro);
      padding-left: 10px;
      margin-bottom: 18px;
      text-align: left;
    }
.articulo-propio .section-intro h2{
      font-size: clamp(1.4rem, 4vw, 2.4rem);
      font-weight: 700;
      color: var(--azul);
      line-height: 1.2;
      margin-bottom: 18px;
    }
.articulo-propio .section-intro p{
      font-size: clamp(0.88rem, 2vw, 1.05rem);
      color: var(--texto-suave);
      line-height: 1.85;
      font-weight: 300;
    }
.articulo-propio .productos{
      background: var(--blanco);
      padding: clamp(48px, 7vw, 72px) 0;
    }
.articulo-propio .productos-inner{
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 clamp(20px, 5vw, 48px);
    }
.articulo-propio .productos-header{
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: clamp(28px, 4vw, 48px);
      flex-wrap: wrap;
    }
.articulo-propio .productos-header h2{
      font-size: clamp(1.4rem, 3.5vw, 2.4rem);
      font-weight: 700;
      color: var(--azul);
      line-height: 1.1;
    }
.articulo-propio .productos-header h2 em{
      font-style: normal;
      color: var(--azul-claro);
      display: block;
    }
.articulo-propio .productos-header p{
      font-size: clamp(0.8rem, 1.8vw, 0.9rem);
      color: var(--texto-suave);
      max-width: 280px;
      font-weight: 300;
    }
.articulo-propio .productos-grid{
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: clamp(14px, 2vw, 20px);
    }
.articulo-propio .prod-card{
      background: var(--fondo);
      border: 1px solid rgba(19,46,106,0.08);
      border-radius: 6px;
      overflow: hidden;
      transition: transform 0.25s, box-shadow 0.25s;
    }
.articulo-propio .prod-card:hover{
      transform: translateY(-5px);
      box-shadow: 0 12px 36px rgba(19,46,106,0.1);
    }
.articulo-propio .prod-card-visual{
      height: clamp(120px, 18vw, 180px);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 10px;
      position: relative;
      overflow: hidden;
    }
.articulo-propio .prod-sillas .prod-card-visual{
      background: linear-gradient(135deg, #dce8f5 0%, #b8d4ea 100%);
      border-bottom: 3px solid var(--azul);
    }
.articulo-propio .prod-mesas .prod-card-visual{
      background: linear-gradient(135deg, #d4eaf5 0%, #a8cfe0 100%);
      border-bottom: 3px solid var(--azul-claro);
    }
.articulo-propio .prod-exteriores .prod-card-visual{
      background: linear-gradient(135deg, #e0edf5 0%, #b4cedd 100%);
      border-bottom: 3px solid var(--gris);
    }
.articulo-propio .prod-card-icon{
      font-size: clamp(2rem, 5vw, 3rem);
      line-height: 1;
    }
.articulo-propio .prod-card-label{
      font-size: 0.6rem;
      font-weight: 700;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--azul);
      opacity: 0.5;
    }
.articulo-propio .prod-card-body{
      padding: clamp(16px, 2.5vw, 24px) clamp(14px, 2vw, 20px) clamp(18px, 2.5vw, 24px);
    }
.articulo-propio .prod-card-body h3{
      font-size: clamp(0.85rem, 2vw, 1rem);
      font-weight: 700;
      color: var(--azul);
      margin-bottom: 8px;
    }
.articulo-propio .prod-card-body p{
      font-size: clamp(0.75rem, 1.6vw, 0.85rem);
      color: var(--texto-suave);
      line-height: 1.6;
      font-weight: 300;
      margin-bottom: 14px;
    }
.articulo-propio .prod-tag{
      font-size: 0.65rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--azul);
      background: rgba(19,46,106,0.07);
      padding: 4px 10px;
      border-radius: 2px;
      display: inline-block;
    }
.articulo-propio .mundial{
      background: var(--azul);
      padding: clamp(52px, 8vw, 88px) 0;
      position: relative;
      overflow: hidden;
    }
.articulo-propio .mundial::before{
      content: '2026';
      position: absolute;
      right: -20px; top: 50%;
      transform: translateY(-50%);
      font-size: clamp(8rem, 20vw, 18rem);
      font-weight: 800;
      color: rgba(255,255,255,0.03);
      line-height: 1;
      pointer-events: none;
      letter-spacing: -0.05em;
    }
.articulo-propio .mundial-inner{
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 clamp(20px, 5vw, 48px);
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(32px, 5vw, 72px);
      align-items: center;
      position: relative;
      z-index: 1;
    }
.articulo-propio .mundial-text .section-tag{
      color: var(--azul-claro);
      border-left-color: var(--azul-claro);
    }
.articulo-propio .mundial-text h2{
      font-size: clamp(1.4rem, 3.5vw, 2.6rem);
      font-weight: 700;
      color: var(--blanco);
      line-height: 1.15;
      margin-bottom: 20px;
    }
.articulo-propio .mundial-text h2 em{
      font-style: normal;
      color: var(--azul-claro);
    }
.articulo-propio .mundial-text p{
      font-size: clamp(0.85rem, 1.8vw, 0.98rem);
      color: rgba(255,255,255,0.65);
      line-height: 1.8;
      font-weight: 300;
      margin-bottom: 14px;
    }
.articulo-propio .mundial-text p strong{
      color: var(--blanco);
      font-weight: 600;
    }
.articulo-propio .mundial-stats{
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
.articulo-propio .mstat{
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(148,189,213,0.15);
      border-radius: 6px;
      padding: clamp(16px, 2.5vw, 22px) clamp(16px, 2.5vw, 24px);
      display: flex;
      align-items: center;
      gap: clamp(14px, 2.5vw, 22px);
    }
.articulo-propio .mstat-num{
      font-size: clamp(1.6rem, 4vw, 2.4rem);
      font-weight: 700;
      color: var(--blanco);
      line-height: 1;
      min-width: clamp(64px, 10vw, 86px);
      flex-shrink: 0;
    }
.articulo-propio .mstat-num small{
      font-size: clamp(0.7rem, 1.5vw, 0.9rem);
      color: var(--azul-claro);
    }
.articulo-propio .mstat-info h4{
      font-size: clamp(0.78rem, 1.6vw, 0.9rem);
      font-weight: 600;
      color: var(--blanco);
      margin-bottom: 3px;
    }
.articulo-propio .mstat-info p{
      font-size: clamp(0.7rem, 1.4vw, 0.78rem);
      color: rgba(255,255,255,0.45);
      margin: 0;
      font-weight: 300;
      line-height: 1.5;
    }
.articulo-propio .porque{
      padding: clamp(52px, 8vw, 80px) 0;
      background: var(--fondo);
    }
.articulo-propio .porque-inner{
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 clamp(20px, 5vw, 48px);
      display: grid;
      grid-template-columns: 360px 1fr;
      gap: clamp(32px, 5vw, 72px);
      align-items: start;
    }
.articulo-propio .porque-left h2{
      font-size: clamp(1.4rem, 3.5vw, 2.2rem);
      font-weight: 700;
      color: var(--azul);
      line-height: 1.15;
      margin-bottom: 16px;
    }
.articulo-propio .porque-left h2 em{
      font-style: normal;
      color: var(--azul-claro);
    }
.articulo-propio .porque-left p{
      font-size: clamp(0.82rem, 1.8vw, 0.95rem);
      color: var(--texto-suave);
      line-height: 1.8;
      font-weight: 300;
    }
.articulo-propio .checklist{
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
.articulo-propio .checklist li{
      display: flex;
      align-items: flex-start;
      gap: 14px;
      background: var(--blanco);
      border: 1px solid rgba(19,46,106,0.07);
      border-radius: 5px;
      padding: clamp(14px, 2vw, 20px) clamp(14px, 2vw, 22px);
      transition: border-color 0.2s;
    }
.articulo-propio .checklist li:hover{ border-color: var(--azul-claro); }
.articulo-propio .check-dot{
      width: 9px; height: 9px;
      background: var(--azul-claro);
      border-radius: 50%;
      flex-shrink: 0;
      margin-top: 5px;
    }
.articulo-propio .check-text h4{
      font-size: clamp(0.82rem, 1.8vw, 0.92rem);
      font-weight: 600;
      color: var(--azul);
      margin-bottom: 3px;
    }
.articulo-propio .check-text p{
      font-size: clamp(0.75rem, 1.5vw, 0.82rem);
      color: var(--texto-suave);
      font-weight: 300;
      line-height: 1.5;
    }
.articulo-propio .quote-block{
      background: var(--blanco);
      padding: clamp(52px, 8vw, 72px) clamp(20px, 5vw, 48px);
    }
.articulo-propio .quote-inner{
      max-width: 740px;
      margin: 0 auto;
      text-align: center;
      position: relative;
    }
.articulo-propio .quote-mark{
      font-size: clamp(4rem, 10vw, 7rem);
      font-weight: 700;
      color: var(--azul-claro);
      opacity: 0.2;
      line-height: 1;
      font-family: Georgia, serif;
      margin-bottom: -20px;
    }
.articulo-propio .quote-inner blockquote{
      font-size: clamp(0.95rem, 2.5vw, 1.25rem);
      font-weight: 500;
      color: var(--azul);
      line-height: 1.75;
      font-style: italic;
      margin-bottom: 20px;
    }
.articulo-propio .quote-inner cite{
      font-size: 0.72rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--gris);
      font-style: normal;
      font-weight: 500;
    }
.articulo-propio .tips{
      background: var(--fondo);
      padding: clamp(52px, 8vw, 80px) 0;
    }
.articulo-propio .tips-inner{
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 clamp(20px, 5vw, 48px);
    }
.articulo-propio .tips-header{
      text-align: center;
      margin-bottom: clamp(32px, 5vw, 52px);
    }
.articulo-propio .tips-header h2{
      font-size: clamp(1.4rem, 3.5vw, 2.2rem);
      font-weight: 700;
      color: var(--azul);
      margin-bottom: 10px;
      line-height: 1.2;
    }
.articulo-propio .tips-header p{
      font-size: clamp(0.82rem, 1.8vw, 0.95rem);
      color: var(--texto-suave);
      font-weight: 300;
    }
.articulo-propio .tips-grid{
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: clamp(12px, 2vw, 20px);
    }
.articulo-propio .tip{
      background: var(--blanco);
      border: 1px solid rgba(19,46,106,0.07);
      border-radius: 6px;
      padding: clamp(20px, 3vw, 28px) clamp(16px, 2.5vw, 24px);
      position: relative;
      overflow: hidden;
      transition: transform 0.2s;
    }
.articulo-propio .tip:hover{ transform: translateY(-4px); }
.articulo-propio .tip::before{
      content: '';
      position: absolute;
      left: 0; top: 0; bottom: 0;
      width: 3px;
      background: var(--azul);
    }
.articulo-propio .tip-num{
      font-size: clamp(1.8rem, 4vw, 2.4rem);
      font-weight: 800;
      color: rgba(19,46,106,0.07);
      line-height: 1;
      margin-bottom: 6px;
    }
.articulo-propio .tip h4{
      font-size: clamp(0.82rem, 1.8vw, 0.95rem);
      font-weight: 600;
      color: var(--azul);
      margin-bottom: 8px;
      line-height: 1.3;
    }
.articulo-propio .tip p{
      font-size: clamp(0.75rem, 1.5vw, 0.84rem);
      color: var(--texto-suave);
      line-height: 1.6;
      font-weight: 300;
    }
.articulo-propio .cta-final{
      background: linear-gradient(135deg, #0d1a3d 0%, #132E6A 100%);
      padding: clamp(64px, 10vw, 96px) clamp(20px, 5vw, 48px);
      text-align: center;
      position: relative;
      overflow: hidden;
    }
.articulo-propio .cta-final::before{
      content: '';
      position: absolute; inset: 0;
      background-image:
        linear-gradient(rgba(148,189,213,0.04) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148,189,213,0.04) 1px, transparent 1px);
      background-size: 48px 48px;
    }
.articulo-propio .cta-final-inner{
      position: relative;
      z-index: 1;
      max-width: 640px;
      margin: 0 auto;
    }
.articulo-propio .cta-final h2{
      font-size: clamp(1.6rem, 5vw, 3rem);
      font-weight: 700;
      color: var(--blanco);
      line-height: 1.1;
      margin-bottom: 18px;
    }
.articulo-propio .cta-final h2 span{ color: var(--azul-claro); }
.articulo-propio .cta-final p{
      font-size: clamp(0.85rem, 2vw, 1rem);
      color: rgba(255,255,255,0.6);
      margin-bottom: clamp(28px, 5vw, 44px);
      font-weight: 300;
      line-height: 1.75;
    }
.articulo-propio .cta-btns{
      display: flex;
      gap: 14px;
      justify-content: center;
      flex-wrap: wrap;
    }
.articulo-propio .btn-wa{
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: #25d366;
      color: var(--blanco);
      font-size: clamp(0.78rem, 2vw, 0.9rem);
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      padding: clamp(14px, 2.5vw, 18px) clamp(20px, 4vw, 36px);
      border-radius: 3px;
      text-decoration: none;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 6px 24px rgba(37,211,102,0.35);
    }
.articulo-propio .btn-wa:hover{ transform: translateY(-2px); box-shadow: 0 10px 36px rgba(37,211,102,0.5); }
.articulo-propio .btn-wa svg{ width: 18px; height: 18px; fill: #fff; flex-shrink: 0; }
.articulo-propio .btn-cat{
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: transparent;
      color: rgba(255,255,255,0.65);
      font-size: clamp(0.78rem, 2vw, 0.88rem);
      font-weight: 500;
      padding: clamp(14px, 2.5vw, 18px) clamp(16px, 3vw, 28px);
      border-radius: 3px;
      text-decoration: none;
      border: 1px solid rgba(255,255,255,0.18);
      transition: border-color 0.2s, color 0.2s;
    }
.articulo-propio .btn-cat:hover{ border-color: var(--azul-claro); color: var(--azul-claro); }
.articulo-propio footer{
      background: #0a1530;
      padding: clamp(20px, 4vw, 32px) clamp(20px, 5vw, 48px);
      text-align: center;
    }
.articulo-propio footer p{
      font-size: clamp(0.68rem, 1.5vw, 0.78rem);
      color: rgba(255,255,255,0.25);
      letter-spacing: 0.06em;
      line-height: 1.6;
    }
.articulo-propio footer strong{ color: var(--azul-claro); }
@keyframes pulse{
      0%, 100% { opacity: 0.4; transform: scale(1); }
      50%       { opacity: 1;   transform: scale(1.3); }
    }
@media (max-width: 900px){
.articulo-propio .hero-inner{
        grid-template-columns: 1fr;
      }
.articulo-propio .hero-card{ display: none; }
.articulo-propio .mundial-inner{
        grid-template-columns: 1fr;
      }
.articulo-propio .porque-inner{
        grid-template-columns: 1fr;
        gap: 32px;
      }
.articulo-propio .porque-left{ max-width: 100%; }
.articulo-propio .tips-grid{
        grid-template-columns: repeat(2, 1fr);
      }
.articulo-propio .productos-header{
        flex-direction: column;
        align-items: flex-start;
      }
.articulo-propio .productos-header p{ max-width: 100%; }
}
@media (max-width: 600px){
.articulo-propio .nav-logo-sub{ display: none; }
.articulo-propio .hero-inner{
        padding-top: 40px;
        padding-bottom: 48px;
      }
.articulo-propio .hero h1{ font-size: 1.75rem; }
.articulo-propio .hero-btns{
        flex-direction: column;
      }
.articulo-propio .btn-primary, .articulo-propio .btn-outline{
        width: 100%;
        justify-content: center;
      }
.articulo-propio .productos-grid{
        grid-template-columns: 1fr;
      }
.articulo-propio .mstat{
        flex-direction: row;
        gap: 16px;
      }
.articulo-propio .tips-grid{
        grid-template-columns: 1fr;
      }
.articulo-propio .cta-btns{
        flex-direction: column;
        align-items: stretch;
      }
.articulo-propio .btn-wa, .articulo-propio .btn-cat{
        width: 100%;
        justify-content: center;
      }
.articulo-propio .quote-mark{ font-size: 3.5rem; margin-bottom: -12px; }
}
@media (max-width: 380px){
.articulo-propio .hero h1{ font-size: 1.5rem; }
.articulo-propio .nav-logo-text{ font-size: 0.9rem; }
.articulo-propio .nav-cta{ padding: 8px 10px; font-size: 0.6rem; }
}

