.articulo-propio *, .articulo-propio *::before, .articulo-propio *::after{
  margin:0;
  padding:0;
  box-sizing:border-box;
}
.articulo-propio{
  scroll-behavior:smooth;
  overflow-x:hidden;
  width:100%;
}
.articulo-propio{
  width:100%;
  max-width:100%;
  overflow-x:hidden !important;

  font-family:'Montserrat',sans-serif;

  background:#fff;
  color:#111;

  -webkit-font-smoothing:antialiased;
}
.articulo-propio img{
  width:100%;
  max-width:100%;
  display:block;
  height:auto;
}
.articulo-propio a{
  text-decoration:none;
  color:inherit;
}
.articulo-propio section{
  width:100%;
  overflow:hidden;
  position:relative;
}
.articulo-propio{

  --primary:#132E6A;
  --secondary:#94BDD5;
  --light:#D1D1CF;
  --white:#fff;
  --gray:#6f6f6f;
  --black:#111;

  --font-title:'Bebas Neue',sans-serif;
  --font-body:'Montserrat',sans-serif;

  --container:1280px;

  --radius:18px;

}
.articulo-propio .container{
  width:100%;
  max-width:1280px;

  margin-inline:auto;

  padding-left:clamp(18px,5vw,60px);
  padding-right:clamp(18px,5vw,60px);
}
.articulo-propio .reveal{
  opacity:0;
  transform:translateY(30px);
  transition:.7s ease;
}
.articulo-propio .reveal.visible{
  opacity:1;
  transform:none;
}
.articulo-propio .d1{transition-delay:.1s;}
.articulo-propio .d2{transition-delay:.2s;}
.articulo-propio .d3{transition-delay:.3s;}
.articulo-propio .hero-nav{
  position:absolute;
  top:0;
  left:0;

  width:100%;

  z-index:50;

  padding:20px 0;
}
.articulo-propio .hero-nav .container{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:20px;
}
.articulo-propio .logo{
  font-family:var(--font-title);

  font-size:clamp(1.8rem,4vw,2.8rem);

  letter-spacing:2px;

  color:#fff;
}
.articulo-propio .nav-links{
  display:flex;
  list-style:none;
  gap:24px;
}
.articulo-propio .nav-links a{
  color:rgba(255,255,255,.8);

  font-size:12px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.1em;

  transition:.25s;
}
.articulo-propio .nav-links a:hover{
  color:#fff;
}
.articulo-propio .hero{
  min-height:100svh;

  display:flex;
  align-items:flex-end;

  padding-top:140px;
  padding-bottom:70px;
}
.articulo-propio .hero-bg{
  position:absolute;
  inset:0;

  background-image:url("https://ofitodo.com/wp-content/uploads/2026/05/ChatGPT-Image-5-mar-2026_-02_57_46-p.m.webp");

  background-size:cover;
  background-position:center;

  z-index:0;
}
.articulo-propio .hero-bg::after{
  content:'';

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    to top,
    rgba(19,46,106,.97),
    rgba(19,46,106,.65),
    rgba(19,46,106,.20)
  );
}
.articulo-propio .hero-content{
  position:relative;
  z-index:10;

  width:100%;
  max-width:850px;
}
.articulo-propio .hero-tags{
  display:flex;
  flex-wrap:wrap;
  gap:10px;

  margin-bottom:22px;
}
.articulo-propio .tag{
  padding:8px 14px;

  border-radius:999px;

  background:rgba(255,255,255,.12);

  border:1px solid rgba(255,255,255,.2);

  color:#fff;

  font-size:10px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.1em;
}
.articulo-propio .hero h1{
  font-family:var(--font-title);

  font-size:clamp(2.5rem,10vw,7rem);

  line-height:.9;

  color:#fff;

  margin-bottom:18px;

  overflow-wrap:break-word;
  word-break:break-word;
  hyphens:auto;
}
.articulo-propio .hero p{
  font-size:clamp(.95rem,2vw,1.1rem);

  line-height:1.8;

  color:rgba(255,255,255,.82);

  margin-bottom:34px;

  max-width:650px;
}
.articulo-propio .hero-buttons{
  display:flex;
  flex-wrap:wrap;
  gap:14px;
}
.articulo-propio .btn{
  min-height:52px;

  padding:14px 28px;

  border-radius:10px;

  display:inline-flex;
  align-items:center;
  justify-content:center;

  text-align:center;

  font-size:12px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.08em;

  transition:.25s;

  border:2px solid transparent;
}
.articulo-propio .primary{
  background:var(--secondary);
  color:var(--primary);
}
.articulo-propio .primary:hover{
  background:#fff;
}
.articulo-propio .outline{
  border-color:rgba(255,255,255,.45);
  color:#fff;
}
.articulo-propio .outline:hover{
  background:rgba(255,255,255,.08);
  border-color:#fff;
}
.articulo-propio .hero-number{
  position:absolute;

  right:3%;
  bottom:20px;

  font-family:var(--font-title);

  font-size:clamp(5rem,18vw,14rem);

  color:rgba(255,255,255,.05);

  line-height:1;
}
.articulo-propio .about{
  padding:100px 0;
}
.articulo-propio .grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:70px;
}
.articulo-propio .section-label{
  display:block;

  margin-bottom:14px;

  font-size:11px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.2em;

  color:var(--secondary);
}
.articulo-propio .about-title{
  font-family:var(--font-title);

  font-size:clamp(2.2rem,6vw,4.2rem);

  line-height:.95;

  color:var(--primary);

  margin-bottom:24px;

  overflow-wrap:break-word;
  word-break:break-word;
}
.articulo-propio .about p{
  font-size:15px;

  line-height:1.9;

  color:var(--gray);

  margin-bottom:18px;
}
.articulo-propio .about-card{
  background:var(--light);

  padding:38px;

  border-radius:24px;
}
.articulo-propio .meta{
  display:flex;
  justify-content:space-between;

  gap:16px;

  padding:18px 0;

  border-bottom:1px solid rgba(0,0,0,.08);
}
.articulo-propio .meta:last-child{
  border:none;
}
.articulo-propio .meta span:first-child{
  font-size:11px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.1em;

  color:var(--secondary);
}
.articulo-propio .meta span:last-child{
  font-weight:600;

  color:var(--primary);

  text-align:right;
}
.articulo-propio .gallery{
  background:var(--primary);

  padding:100px 0;
}
.articulo-propio .gallery-header{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:34px;
}
.articulo-propio .gallery-title{
  font-family:var(--font-title);

  font-size:clamp(2.5rem,6vw,4.5rem);

  line-height:.95;

  color:#fff;
}
.articulo-propio .gallery-count{
  font-family:var(--font-title);

  font-size:clamp(2rem,5vw,4rem);

  color:rgba(255,255,255,.15);
}
.articulo-propio .gallery-grid{
  display:grid;

  grid-template-columns:1.5fr 1fr;

  gap:14px;
}
.articulo-propio .gallery-main, .articulo-propio .gallery-small{
  border-radius:20px;
  overflow:hidden;
}
.articulo-propio .gallery-main{
  min-height:600px;
}
.articulo-propio .gallery-small{
  min-height:292px;
}
.articulo-propio .gallery-main img, .articulo-propio .gallery-small img{
  width:100%;
  height:100%;
  object-fit:cover;

  transition:transform .55s ease;
}
.articulo-propio .gallery-main:hover img, .articulo-propio .gallery-small:hover img{
  transform:scale(1.04);
}
.articulo-propio .gallery-footer{
  margin-top:28px;
  text-align:center;
}
.articulo-propio .btn-light{
  border:2px solid rgba(255,255,255,.4);
  color:#fff;
}
.articulo-propio .btn-light:hover{
  border-color:#fff;
  background:rgba(255,255,255,.08);
}
.articulo-propio .metrics{
  padding:100px 0;
}
.articulo-propio .metrics-header{
  text-align:center;
  margin-bottom:42px;
}
.articulo-propio .metrics-title{
  font-family:var(--font-title);

  font-size:clamp(2.2rem,5vw,4rem);

  color:var(--primary);
}
.articulo-propio .metric-grid{
  display:grid;

  grid-template-columns:repeat(4,1fr);

  gap:4px;
}
.articulo-propio .metric{
  background:var(--light);

  padding:50px 24px;

  text-align:center;

  transition:.25s;
}
.articulo-propio .metric:hover{
  background:var(--secondary);

  transform:translateY(-5px);
}
.articulo-propio .metric h3{
  font-family:var(--font-title);

  font-size:clamp(2.5rem,6vw,4.5rem);

  color:var(--primary);
}
.articulo-propio .metric p{
  margin-top:10px;

  font-size:14px;

  color:var(--gray);

  line-height:1.5;
}
.articulo-propio .cta{
  background:var(--primary);

  padding:110px 0;
}
.articulo-propio .cta-inner{
  display:grid;

  grid-template-columns:1fr auto;

  gap:60px;

  align-items:center;
}
.articulo-propio .cta h2{
  font-family:var(--font-title);

  font-size:clamp(2.8rem,9vw,6rem);

  line-height:.92;

  color:#fff;

  margin-bottom:18px;

  overflow-wrap:break-word;
  word-break:break-word;
}
.articulo-propio .cta h2 span{
  color:var(--secondary);
}
.articulo-propio .cta-desc{
  font-size:15px;

  line-height:1.9;

  color:rgba(255,255,255,.78);

  margin-bottom:32px;

  max-width:560px;
}
.articulo-propio .cta-buttons{
  display:flex;
  flex-wrap:wrap;
  gap:14px;
}
.articulo-propio .btn-cta{
  background:var(--secondary);
  color:var(--primary);
}
.articulo-propio .cta-contact{
  display:flex;
  flex-direction:column;
  gap:20px;
}
.articulo-propio .contact-label{
  font-size:10px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.16em;

  color:var(--secondary);
}
.articulo-propio .contact-val{
  color:#fff;
  font-weight:600;
}
.articulo-propio footer{
  background:#081530;
  padding:30px 0;
}
.articulo-propio .footer-inner{
  display:flex;
  justify-content:space-between;
  align-items:center;

  flex-wrap:wrap;

  gap:20px;
}
.articulo-propio .footer-logo{
  font-family:var(--font-title);

  font-size:24px;

  color:#fff;
}
.articulo-propio .footer-copy{
  font-size:12px;

  color:rgba(255,255,255,.4);
}
.articulo-propio .footer-links{
  display:flex;
  list-style:none;
  gap:20px;
}
.articulo-propio .footer-links a{
  font-size:11px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.1em;

  color:rgba(255,255,255,.5);
}
@media(max-width:900px){
.articulo-propio .nav-links{
    display:none;
  }
.articulo-propio .hero-number{
    display:none;
  }
.articulo-propio .about, .articulo-propio .gallery, .articulo-propio .metrics, .articulo-propio .cta{
    padding:70px 0;
  }
.articulo-propio .grid{
    grid-template-columns:1fr;
    gap:40px;
  }
.articulo-propio .gallery-grid{
    grid-template-columns:1fr;
  }
.articulo-propio .gallery-main{
    min-height:320px;
  }
.articulo-propio .gallery-small{
    min-height:220px;
  }
.articulo-propio .metric-grid{
    grid-template-columns:1fr 1fr;
  }
.articulo-propio .cta-inner{
    grid-template-columns:1fr;
  }
}
@media(max-width:560px){
.articulo-propio .container{
    padding-left:24px;
    padding-right:24px;
  }
.articulo-propio .hero{
    min-height:auto;

    padding-top:120px;
    padding-bottom:50px;
  }
.articulo-propio .hero h1{
    font-size:2.6rem;
  }
.articulo-propio .about-title{
    font-size:2.2rem;
  }
.articulo-propio .cta h2{
    font-size:2.5rem;
  }
.articulo-propio .hero-buttons, .articulo-propio .cta-buttons{
    flex-direction:column;
  }
.articulo-propio .btn{
    width:100%;
  }
.articulo-propio .gallery-header{
    flex-direction:column;
    align-items:flex-start;
  }
.articulo-propio .gallery-main{
    min-height:240px;
  }
.articulo-propio .gallery-small{
    min-height:180px;
  }
.articulo-propio .metric-grid{
    grid-template-columns:1fr;
  }
.articulo-propio .meta{
    flex-direction:column;
    align-items:flex-start;
    gap:6px;
  }
.articulo-propio .meta span:last-child{
    text-align:left;
  }
.articulo-propio .footer-inner{
    flex-direction:column;
    text-align:center;
  }
}
@media(max-width:360px){
.articulo-propio .container{
    padding-left:20px;
    padding-right:20px;
  }
.articulo-propio .hero h1{
    font-size:2.2rem;
  }
.articulo-propio .about-title{
    font-size:2rem;
  }
.articulo-propio .cta h2{
    font-size:2.2rem;
  }
}

/* El script del autor no se conserva: se fija el estado final visible */
.articulo-propio .reveal{opacity:1;visibility:visible;transform:none;}

