.articulo-propio .ofi-wrap{
    --navy:#132E6A;
    --navy-deep:#0d2050;
    --blue:#94bdd5;
    --blue-soft:#c7dce9;
    --gray:#808080;
    --gray-light:#D1D1CF;
    --off-white:#f7f7f6;
    --white:#ffffff;
    --whatsapp:#25D366;

    --font-title:'Poppins', sans-serif;      /* similar a ITC Bauhaus */
    --font-subtitle:'Work Sans', sans-serif; /* similar a Canva Sans */
    --font-text:'Montserrat', sans-serif;    /* Montserrat Regular */

    font-family: var(--font-text);
    color: var(--navy-deep);
    background: var(--white);
    overflow-x: hidden;
    box-sizing: border-box;
  }
.articulo-propio .ofi-wrap *, .articulo-propio .ofi-wrap *::before, .articulo-propio .ofi-wrap *::after{
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
  }
.articulo-propio .ofi-wrap img{ max-width:100%; display:block; }
.articulo-propio .ofi-wrap a{ text-decoration:none; }
.articulo-propio .ofi-section{
    width:100%;
    padding: clamp(48px, 8vw, 96px) clamp(20px, 6vw, 80px);
  }
.articulo-propio .ofi-inner{
    max-width: 1160px;
    margin: 0 auto;
    width:100%;
  }
.articulo-propio .ofi-wrap h1, .articulo-propio .ofi-wrap h2, .articulo-propio .ofi-wrap h3{
    font-family: var(--font-title);
    font-weight: 700;
    line-height: 1.15;
    margin: 0;
    overflow-wrap: break-word;
    word-break: normal;
    hyphens: auto;
    white-space: normal;
    max-width: 100%;
  }
.articulo-propio .ofi-hero{
    /* [EDITAR] Cambia la URL dentro de url('') por tu imagen de fondo.
       El degradado navy queda ENCIMA de la imagen para que el título
       siga siendo legible sin importar la foto que uses. */
    background:
      linear-gradient(155deg, rgba(19,46,106,0.88) 0%, rgba(13,32,80,0.92) 100%),
      url('') center center / cover no-repeat;
    color: var(--white);
    padding: clamp(56px,10vw,110px) clamp(20px,6vw,80px);
    text-align:center;
    position: relative;
  }
.articulo-propio .ofi-hero::after{
    content:"";
    position:absolute; left:0; right:0; bottom:0;
    height:6px;
    background: linear-gradient(90deg, var(--blue), var(--gray-light), var(--blue));
  }
.articulo-propio .ofi-eyebrow{
    font-family: var(--font-subtitle);
    letter-spacing: 3px;
    text-transform: uppercase;
    font-size: clamp(11px,1.6vw,13px);
    color: var(--blue-soft);
    margin-bottom: 18px;
    display:inline-block;
  }
.articulo-propio .ofi-hero h1{
    font-size: clamp(28px, 5.2vw, 54px);
    max-width: 850px;
    margin: 0 auto 20px;
    color: var(--white) !important;
  }
.articulo-propio .ofi-hero p{
    font-family: var(--font-subtitle);
    font-weight: 400;
    font-size: clamp(15px, 2.2vw, 19px);
    color: var(--blue-soft) !important;
    max-width: 620px;
    margin: 0 auto;
    line-height: 1.6;
  }
.articulo-propio .ofi-chair-icon{
    width: 46px; height: 46px;
    margin: 0 auto 22px;
    opacity: .9;
  }
.articulo-propio .ofi-intro{ background: var(--off-white); }
.articulo-propio .ofi-intro-grid{
    display:grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: clamp(28px,5vw,60px);
    align-items:center;
  }
.articulo-propio .ofi-tag{
    display:inline-block;
    font-family: var(--font-subtitle);
    font-size: 12px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--navy);
    background: var(--blue-soft);
    padding: 6px 14px;
    border-radius: 30px;
    margin-bottom: 16px;
  }
.articulo-propio .ofi-intro h2{
    font-size: clamp(24px, 3.6vw, 36px);
    color: var(--navy);
    margin-bottom: 18px;
  }
.articulo-propio .ofi-intro p{
    font-size: clamp(15px, 1.9vw, 17px);
    line-height: 1.75;
    color: #3c3c3c;
    font-weight: 300;
    margin-bottom: 14px;
  }
.articulo-propio .ofi-intro-img{
    border-radius: 14px;
    overflow:hidden;
    box-shadow: 0 18px 40px -12px rgba(19,46,106,0.35);
    aspect-ratio: 4/3;
    object-fit: cover;
    width:100%;
    height:100%;
  }
.articulo-propio .ofi-gallery{ background: var(--white); }
.articulo-propio .ofi-gallery-head{
    text-align:center;
    max-width: 640px;
    margin: 0 auto clamp(32px,5vw,56px);
  }
.articulo-propio .ofi-gallery-head h2{
    font-size: clamp(24px,3.6vw,36px);
    color: var(--navy);
    margin-bottom: 12px;
  }
.articulo-propio .ofi-gallery-head p{
    font-family: var(--font-subtitle);
    font-size: clamp(14px,1.8vw,16px);
    color: var(--gray);
  }
.articulo-propio .ofi-grid{
    display:grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 22px;
  }
.articulo-propio .ofi-card{
    position:relative;
    border-radius: 14px;
    overflow:hidden;
    background: var(--gray-light);
    aspect-ratio: 1/1;
  }
.articulo-propio .ofi-card img{
    width:100%; height:100%; object-fit:cover;
    transition: transform .5s ease;
  }
.articulo-propio .ofi-card:hover img{ transform: scale(1.06); }
.articulo-propio .ofi-card-caption{
    position:absolute; left:0; right:0; bottom:0;
    padding: 16px 18px;
    background: linear-gradient(to top, rgba(13,32,80,0.88), rgba(13,32,80,0));
    color: var(--white);
    font-family: var(--font-subtitle);
    font-size: 14px;
    font-weight: 500;
  }
.articulo-propio .ofi-cierre{
    background: linear-gradient(155deg, var(--navy-deep) 0%, var(--navy) 100%);
    color: var(--white);
    text-align:center;
  }
.articulo-propio .ofi-cierre h2{
    font-size: clamp(24px,3.8vw,38px);
    max-width: 700px;
    margin: 0 auto 18px;
    color: var(--white) !important;
  }
.articulo-propio .ofi-cierre p{
    font-family: var(--font-subtitle);
    font-size: clamp(15px,2vw,17px);
    color: var(--blue-soft) !important;
    max-width: 560px;
    margin: 0 auto 36px;
    line-height: 1.6;
  }
.articulo-propio .ofi-btn-row{
    display:flex;
    flex-wrap: wrap;
    justify-content:center;
    gap: 16px;
  }
.articulo-propio .ofi-btn{
    font-family: var(--font-subtitle);
    font-weight: 600;
    font-size: 15px;
    padding: 15px 32px;
    border-radius: 8px;
    display:inline-flex;
    align-items:center;
    gap: 10px;
    transition: all .25s ease;
    white-space: nowrap;
  }
.articulo-propio .ofi-btn-primary{
    background: var(--blue);
    color: var(--navy-deep);
  }
.articulo-propio .ofi-btn-primary:hover{
    background: var(--white);
    transform: translateY(-2px);
  }
.articulo-propio .ofi-btn-outline{
    background: transparent;
    border: 1.5px solid var(--blue-soft);
    color: var(--white);
  }
.articulo-propio .ofi-btn-outline:hover{
    background: rgba(255,255,255,0.08);
    transform: translateY(-2px);
  }
.articulo-propio .ofi-whatsapp-float{
    position: fixed;
    right: 20px;
    bottom: 20px;
    width: 60px; height: 60px;
    background: var(--whatsapp);
    border-radius: 50%;
    display:flex; align-items:center; justify-content:center;
    box-shadow: 0 8px 22px rgba(0,0,0,0.28);
    z-index: 9999;
    transition: transform .2s ease;
  }
.articulo-propio .ofi-whatsapp-float:hover{ transform: scale(1.08); }
.articulo-propio .ofi-whatsapp-float svg{ width: 30px; height:30px; }
@media (max-width: 900px){
.articulo-propio .ofi-intro-grid{ grid-template-columns: 1fr; }
.articulo-propio .ofi-intro-img{ order:-1; aspect-ratio: 16/9; }
.articulo-propio .ofi-grid{ grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 560px){
.articulo-propio .ofi-section{ padding: 44px 18px; }
.articulo-propio .ofi-hero{ padding: 52px 18px 60px; }
.articulo-propio .ofi-hero h1{ font-size: clamp(26px, 8vw, 34px); line-height:1.2; }
.articulo-propio .ofi-hero p{ font-size: 15px; }
.articulo-propio .ofi-grid{ grid-template-columns: 1fr 1fr; gap: 12px; }
.articulo-propio .ofi-btn-row{ flex-direction: column; align-items: stretch; }
.articulo-propio .ofi-btn{ justify-content:center; width: 100%; }
.articulo-propio .ofi-whatsapp-float{ width: 54px; height:54px; right:14px; bottom:14px; }
.articulo-propio .ofi-card-caption{ font-size: 12.5px; padding: 10px 12px; }
}
@media (max-width: 380px){
.articulo-propio .ofi-grid{ grid-template-columns: 1fr; }
}

/mobiliario-de-oficina-en-aguascalientes.css:
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&family=Montserrat:wght@400;500;600;700&display=swap');
.articulo-propio .oft-article{
      --oft-navy: #132E6A;         /* Navy de marca */
      --oft-navy-deep: #0A1F4D;    /* Navy profundo para fondos oscuros */
      --oft-blue: #4E85B8;         /* Azul de marca saturado (base #94bdd5 intensificado) */
      --oft-blue-pale: #94bdd5;    /* Azul de marca original, para acentos suaves */
      --oft-action: #0B4DE0;       /* Azul cobalto de conversión, dentro de la familia de marca */
      --oft-action-light: #3B76F0;
      --oft-gray: #808080;         /* Gris de marca */
      --oft-gray-light: #D1D1CF;   /* Gris claro de marca */
      --oft-paper: #F4F6F8;
      --oft-ink: #101828;
      --oft-white: #FFFFFF;

      font-family: 'Montserrat', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--oft-ink);
      background: var(--oft-paper);
      max-width: 860px;
      margin: 0 auto;
      padding: 0 20px 60px;
      line-height: 1.7;
    }
.articulo-propio .oft-article *{ box-sizing: border-box; }
.articulo-propio .oft-article h1, .articulo-propio .oft-article h2, .articulo-propio .oft-article h3, .articulo-propio .oft-article .oft-display{
      font-family: 'Poppins', 'Montserrat', sans-serif;
      color: var(--oft-navy);
      letter-spacing: -0.01em;
      font-weight: 700;
    }
.articulo-propio .oft-hero{
      position: relative;
      padding: 56px 32px 40px;
      margin: 32px 0 40px;
      background: linear-gradient(135deg, var(--oft-navy) 0%, var(--oft-navy-deep) 100%);
      border-radius: 6px;
      overflow: hidden;
      color: var(--oft-white);
      box-shadow: 0 12px 32px rgba(19,46,106,0.25);
    }
.articulo-propio .oft-hero::before{
      content: "";
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(var(--oft-blue-pale) 1px, transparent 1px),
        linear-gradient(90deg, var(--oft-blue-pale) 1px, transparent 1px);
      background-size: 32px 32px;
      opacity: 0.08;
      pointer-events: none;
    }
.articulo-propio .oft-eyebrow{
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: 'Poppins', sans-serif;
      font-size: 12.5px;
      font-weight: 600;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--oft-action-light);
      border: 1px solid rgba(11,77,224,0.55);
      background: rgba(11,77,224,0.1);
      padding: 6px 12px;
      border-radius: 3px;
      position: relative;
      z-index: 1;
    }
.articulo-propio .oft-eyebrow::before{ content: "◆"; font-size: 9px; }
.articulo-propio .oft-hero h1{
      color: var(--oft-white);
      font-size: clamp(28px, 4vw, 40px);
      line-height: 1.15;
      margin: 20px 0 14px;
      position: relative;
      z-index: 1;
      max-width: 20ch;
    }
.articulo-propio .oft-hero p.oft-sub{
      color: #C7D6EA;
      font-size: 17px;
      max-width: 52ch;
      margin: 0 0 26px;
      position: relative;
      z-index: 1;
    }
.articulo-propio .oft-meta-row{
      display: flex;
      flex-wrap: wrap;
      gap: 18px;
      font-size: 13px;
      color: var(--oft-blue-pale);
      font-family: 'Poppins', monospace;
      font-weight: 600;
      position: relative;
      z-index: 1;
      margin-bottom: 24px;
    }
.articulo-propio .oft-meta-row span{ display: flex; align-items: center; gap: 6px; }
.articulo-propio .oft-cta-wsp{
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--oft-action);
      color: var(--oft-white);
      font-weight: 700;
      font-size: 15.5px;
      text-decoration: none;
      padding: 15px 24px;
      border-radius: 4px;
      position: relative;
      z-index: 1;
      box-shadow: 0 6px 18px rgba(11,77,224,0.4);
      transition: background 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
    }
.articulo-propio .oft-cta-wsp:hover{
      background: var(--oft-action-light);
      transform: translateY(-2px);
      box-shadow: 0 10px 22px rgba(11,77,224,0.5);
    }
.articulo-propio .oft-cta-wsp:focus-visible{ outline: 3px solid var(--oft-blue-pale); outline-offset: 2px; }
.articulo-propio .oft-cta-wsp svg{ width: 20px; height: 20px; flex-shrink: 0; }
.articulo-propio .oft-cta-inline{
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      background: var(--oft-white);
      border: 1px solid var(--oft-gray-light);
      border-left: 5px solid var(--oft-action);
      padding: 20px 22px;
      border-radius: 4px;
      margin: 34px 0;
      box-shadow: 0 2px 10px rgba(16,24,40,0.05);
    }
.articulo-propio .oft-cta-inline p{ margin: 0; font-size: 15.5px; color: var(--oft-ink); }
.articulo-propio .oft-cta-inline strong{ color: var(--oft-navy); }
.articulo-propio .oft-article h2{
      font-size: 25px;
      margin: 46px 0 16px;
      padding-bottom: 10px;
      border-bottom: 3px solid var(--oft-action);
      display: inline-block;
    }
.articulo-propio .oft-article h3{
      font-size: 19px;
      margin: 26px 0 10px;
      color: var(--oft-navy);
    }
.articulo-propio .oft-article p{ margin: 0 0 16px; font-size: 16.5px; }
.articulo-propio .oft-article ul, .articulo-propio .oft-article ol{ margin: 0 0 18px; padding-left: 22px; }
.articulo-propio .oft-article li{ margin-bottom: 8px; font-size: 16.5px; }
.articulo-propio .oft-article strong{ color: var(--oft-navy); }
.articulo-propio .oft-spec{
      border: 1px dashed var(--oft-gray);
      border-radius: 4px;
      padding: 20px 22px;
      margin: 28px 0;
      background: var(--oft-white);
      position: relative;
    }
.articulo-propio .oft-spec-tag{
      position: absolute;
      top: -11px;
      left: 18px;
      background: var(--oft-navy);
      color: var(--oft-white);
      font-family: 'Poppins', monospace;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
      padding: 3px 10px;
      border-radius: 3px;
      text-transform: uppercase;
    }
.articulo-propio .oft-spec p:last-child{ margin-bottom: 0; }
.articulo-propio .oft-img-wrap{ margin: 30px 0; }
.articulo-propio .oft-img-wrap img{
      width: 100%;
      height: auto;
      border-radius: 4px;
      display: block;
      border: 1px solid var(--oft-gray-light);
    }
.articulo-propio .oft-img-caption{
      font-size: 13px;
      color: var(--oft-gray);
      margin-top: 8px;
      font-family: 'Poppins', monospace;
    }
.articulo-propio .oft-table-wrap{ overflow-x: auto; margin: 24px 0 32px; }
.articulo-propio table.oft-compare{
      width: 100%;
      border-collapse: collapse;
      font-size: 15px;
      background: var(--oft-white);
      min-width: 480px;
      border-radius: 4px;
      overflow: hidden;
    }
.articulo-propio table.oft-compare th, .articulo-propio table.oft-compare td{
      border: 1px solid var(--oft-gray-light);
      padding: 13px 16px;
      text-align: left;
      vertical-align: top;
    }
.articulo-propio table.oft-compare thead th{
      background: var(--oft-navy);
      color: var(--oft-white);
      font-family: 'Poppins', sans-serif;
      font-weight: 700;
    }
.articulo-propio table.oft-compare tbody tr:nth-child(odd){ background: #F7FAFC; }
.articulo-propio table.oft-compare td:first-child{ font-weight: 700; color: var(--oft-navy); width: 30%; }
.articulo-propio table.oft-compare td.oft-check{ color: #1E8A52; font-weight: 700; }
.articulo-propio table.oft-compare td.oft-cross{ color: #D14343; }
.articulo-propio .oft-steps{ counter-reset: oft-step; list-style: none; padding-left: 0; margin: 24px 0 32px; }
.articulo-propio .oft-steps li{
      counter-increment: oft-step;
      position: relative;
      padding: 4px 0 4px 52px;
      margin-bottom: 20px;
      min-height: 34px;
    }
.articulo-propio .oft-steps li::before{
      content: counter(oft-step, decimal-leading-zero);
      position: absolute;
      left: 0;
      top: 0;
      font-family: 'Poppins', monospace;
      font-size: 14px;
      font-weight: 700;
      color: var(--oft-white);
      background: var(--oft-navy);
      width: 34px;
      height: 34px;
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
.articulo-propio .oft-steps li strong{ display: block; color: var(--oft-navy); font-size: 16.5px; margin-bottom: 3px; }
.articulo-propio .oft-faq{ margin: 22px 0 40px; }
.articulo-propio .oft-faq details{
      background: var(--oft-white);
      border: 1px solid var(--oft-gray-light);
      border-radius: 4px;
      margin-bottom: 10px;
      padding: 4px 0;
    }
.articulo-propio .oft-faq details[open]{ border-color: var(--oft-blue); }
.articulo-propio .oft-faq summary{
      cursor: pointer;
      list-style: none;
      padding: 16px 46px 16px 18px;
      font-weight: 700;
      color: var(--oft-navy);
      font-size: 16px;
      position: relative;
    }
.articulo-propio .oft-faq summary::-webkit-details-marker{ display: none; }
.articulo-propio .oft-faq summary::after{
      content: "+";
      position: absolute;
      right: 18px;
      top: 50%;
      transform: translateY(-50%);
      font-size: 22px;
      color: var(--oft-action);
      line-height: 1;
    }
.articulo-propio .oft-faq details[open] summary::after{ content: "–"; }
.articulo-propio .oft-faq summary:focus-visible{ outline: 2px solid var(--oft-action); outline-offset: -2px; }
.articulo-propio .oft-faq .oft-faq-a{ padding: 0 18px 18px; font-size: 15.5px; color: var(--oft-ink); }
.articulo-propio .oft-faq .oft-faq-a p{ margin: 0; }
.articulo-propio .oft-final-cta{
      background: linear-gradient(135deg, var(--oft-navy-deep) 0%, var(--oft-navy) 100%);
      color: var(--oft-white);
      border-radius: 6px;
      padding: 48px 32px;
      text-align: center;
      margin: 48px 0 20px;
      box-shadow: 0 16px 36px rgba(19,46,106,0.3);
    }
.articulo-propio .oft-final-cta h2{
      color: var(--oft-white);
      border-bottom: none;
      font-size: 27px;
      margin-top: 0;
    }
.articulo-propio .oft-final-cta p{ color: #C7D6EA; max-width: 48ch; margin: 0 auto 26px; }
@media (max-width: 560px){
.articulo-propio .oft-hero{ padding: 40px 20px 30px; }
.articulo-propio .oft-cta-inline{ flex-direction: column; align-items: flex-start; }
}
@media (prefers-reduced-motion: reduce){
.articulo-propio .oft-article *{ transition: none !important; }
}
